      "api.override.body": "{{ value }}\u304C\u51E6\u7406\u30A4\u30F3\u30B9\u30BF\u30F3\u30B9\u306B\u306A\u308A\u307E\u3057\u305F\u3002\u4FE1\u983C\u3067\u304D\u306A\u3044\u5834\u5408\u306F\u300C\u30AD\u30E3\u30F3\u30BB\u30EB\u300D\u3092\u62BC\u3059\u3068\u7121\u8996\u3055\u308C\u307E\u3059\u3002\n\n\u5F8C\u3067\u51E6\u7406\u8A2D\u5B9A\u3067\u9078\u629E\u3092\u5909\u66F4\u3067\u304D\u307E\u3059\u3002",
      "safety.custom_instance.body": "\u30AB\u30B9\u30BF\u30E0\u30A4\u30F3\u30B9\u30BF\u30F3\u30B9\u306F\u30D7\u30E9\u30A4\u30D0\u30B7\u30FC\u3068\u5B89\u5168\u6027\u306E\u30EA\u30B9\u30AF\u3092\u3082\u305F\u3089\u3059\u53EF\u80FD\u6027\u304C\u3042\u308A\u307E\u3059\u3002\n\n\u60AA\u610F\u306E\u3042\u308B\u30A4\u30F3\u30B9\u30BF\u30F3\u30B9\u306F\uFF1A\n1. FreeSaveVideo\u304B\u3089\u96E2\u308C\u3066\u30EA\u30C0\u30A4\u30EC\u30AF\u30C8\u3057\u3001\u8A50\u6B3A\u3092\u8A66\u307F\u308B\u53EF\u80FD\u6027\u304C\u3042\u308A\u307E\u3059\u3002\n2. \u30EA\u30AF\u30A8\u30B9\u30C8\u306B\u95A2\u3059\u308B\u3059\u3079\u3066\u306E\u60C5\u5831\u3092\u30ED\u30B0\u306B\u8A18\u9332\u3057\u3001\u6C38\u4E45\u306B\u4FDD\u5B58\u3057\u3001\u3042\u306A\u305F\u3092\u8FFD\u8DE1\u3059\u308B\u305F\u3081\u306B\u4F7F\u7528\u3059\u308B\u53EF\u80FD\u6027\u304C\u3042\u308A\u307E\u3059\u3002\n3. \u60AA\u610F\u306E\u3042\u308B\u30D5\u30A1\u30A4\u30EB\uFF08\u30DE\u30EB\u30A6\u30A7\u30A2\u306A\u3069\uFF09\u3092\u63D0\u4F9B\u3059\u308B\u53EF\u80FD\u6027\u304C\u3042\u308A\u307E\u3059\u3002\n4. \u5E83\u544A\u3092\u5F37\u5236\u7684\u306B\u8996\u8074\u3055\u305B\u305F\u308A\u3001\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u306B\u6599\u91D1\u3092\u8ACB\u6C42\u3057\u305F\u308A\u3059\u308B\u53EF\u80FD\u6027\u304C\u3042\u308A\u307E\u3059\u3002\n\n\u3053\u306E\u6642\u70B9\u4EE5\u964D\u3001\u5F53\u793E\u306F\u3042\u306A\u305F\u3092\u4FDD\u8B77\u3059\u308B\u3053\u3068\u306F\u3067\u304D\u307E\u305B\u3093\u3002\u3069\u306E\u30A4\u30F3\u30B9\u30BF\u30F3\u30B9\u3092\u4F7F\u7528\u3059\u308B\u304B\u306F\u614E\u91CD\u306B\u5224\u65AD\u3057\u3001\u5E38\u306B\u76F4\u611F\u3092\u4FE1\u983C\u3057\u3066\u304F\u3060\u3055\u3044\u3002\u4F55\u304B\u304C\u304A\u304B\u3057\u3044\u3068\u611F\u3058\u305F\u3089\u3001\u3053\u306E\u30DA\u30FC\u30B8\u306B\u623B\u3063\u3066\u30AB\u30B9\u30BF\u30E0\u30A4\u30F3\u30B9\u30BF\u30F3\u30B9\u3092\u30EA\u30BB\u30C3\u30C8\u3057\u3001GitHub\u3067\u5831\u544A\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
