    captcha_ongoing7 = "\uBD07\uC774 \uC544\uB2CC\uC9C0 \uD655\uC778\uD558\uB294 \uC911\uC785\uB2C8\uB2E4. \uC2A4\uD53C\uB108\uAC00 \uC0AC\uB77C\uC9C8 \uB54C\uAE4C\uC9C0 \uAE30\uB2E4\uB838\uB2E4\uAC00 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.\n\n\uC2DC\uAC04\uC774 \uB108\uBB34 \uC624\uB798 \uAC78\uB9AC\uBA74 \uC54C\uB824\uC8FC\uC138\uC694! \uC6B0\uB9AC\uB294 \uBD07 \uBCF4\uD638\uB97C \uC704\uD574 cloudflare turnstile\uC744 \uC0AC\uC6A9\uD558\uB294\uB370 \uB54C\uB54C\uB85C \uC774\uC720 \uC5C6\uC774 \uC0AC\uB78C\uC744 \uCC28\uB2E8\uD569\uB2C8\uB2E4.";
