      captcha_ongoing: captcha_ongoing7,
      "api.auth.jwt.missing": "\uCC98\uB9AC \uC11C\uBC84\uAC00 \uC778\uAC04 \uC561\uC138\uC2A4 \uD1A0\uD070\uC744 \uBC1B\uC9C0 \uBABB\uD588\uAE30 \uB54C\uBB38\uC5D0 \uB85C\uBD07\uC774 \uC544\uB2CC\uC9C0 \uD655\uC778\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. \uBA87 \uCD08 \uD6C4\uC5D0 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uAC70\uB098 \uD398\uC774\uC9C0\uB97C \uC0C8\uB85C \uACE0\uCE68\uD558\uC138\uC694!",
