      primary_cta: "\u041F\u043E\u043F\u0440\u043E\u0431\u043E\u0432\u0430\u0442\u044C \u0437\u0430\u0433\u0440\u0443\u0437\u0447\u0438\u043A",
      secondary_cta: "\u0421\u043C\u043E\u0442\u0440\u0435\u0442\u044C \u043D\u0430 Bilibili"
