      "saving.timeout": "FreeSaveVideo \u5C1D\u8BD5\u81EA\u52A8\u4FDD\u5B58\u6587\u4EF6\uFF0C\u4F46\u60A8\u7684\u6D4F\u89C8\u5668\u963B\u6B62\u4E86\u5B83\u3002\u60A8\u9700\u8981\u624B\u52A8\u9009\u62E9\u9996\u9009\u7684\u4FDD\u5B58\u65B9\u5F0F\u3002",
      "safety.title": "\u91CD\u8981\u7684\u5B89\u5168\u63D0\u793A",
      "import.body": "\u5BFC\u5165\u672A\u77E5\u6216\u635F\u574F\u7684\u6587\u4EF6\u53EF\u80FD\u4F1A\u610F\u5916\u66F4\u6539\u6216\u7834\u574F FreeSaveVideo \u7684\u529F\u80FD\u3002\u4EC5\u5BFC\u5165\u60A8\u81EA\u5DF1\u5BFC\u51FA\u7684\u4E14\u672A\u4FEE\u6539\u7684\u6587\u4EF6\u3002\u5982\u679C\u6709\u4EBA\u8981\u6C42\u60A8\u5BFC\u5165\u6B64\u6587\u4EF6\uFF0C\u8BF7\u4E0D\u8981\u8FD9\u6837\u505A\u3002\u6211\u4EEC\u4E0D\u5BF9\u5BFC\u5165\u672A\u77E5\u8BBE\u7F6E\u6587\u4EF6\u9020\u6210\u7684\u4EFB\u4F55\u635F\u5BB3\u8D1F\u8D23\u3002",
